from pydantic import BaseModel
from datetime import date

class UserBase(BaseModel):
    email: str

class UserCreate(UserBase):
    password: str

class User(UserBase):
    id: int
    is_active: bool
    is_superuser: bool = False

    model_config = {
        "from_attributes": True
    }

class ContributionData(BaseModel):
    date: date
    count: int

from sqlalchemy.orm import Session
from sqlalchemy import func
import models, schemas
from datetime import date, timedelta

def get_user(db: Session, user_id: int):
    return db.query(models.User).filter(models.User.id == user_id).first()

def get_user_by_email(db: Session, email: str):
    return db.query(models.User).filter(models.User.email == email).first()

def get_users(db: Session, skip: int = 0, limit: int = 100):
    return db.query(models.User).offset(skip).limit(limit).all()

def create_user(db: Session, user: schemas.UserCreate, hashed_password: str):
    db_user = models.User(email=user.email, hashed_password=hashed_password)
    db.add(db_user)
    db.commit()
    db.refresh(db_user)
    return db_user

def get_user_completed_tasks_by_date(db: Session, user_id: int, days_ago: int = 90) -> list[schemas.ContributionData]:
    """
    Retrieves the count of completed tasks by date for a given user within a specified period.
    """
    end_date = date.today()
    start_date = end_date - timedelta(days=days_ago - 1)

    # Use func.date() to extract the date part for grouping
    # Assuming 'updated_at' is the timestamp when the task was marked 'Completed'
    contributions = db.query(
        func.date(models.Task.updated_at).label('contribution_date'),
        func.count(models.Task.id).label('task_count')
    ).filter(
        models.Task.owner_id == user_id,
        models.Task.status == 'Completed',
        func.date(models.Task.updated_at) >= start_date,
        func.date(models.Task.updated_at) <= end_date
    ).group_by(
        func.date(models.Task.updated_at)
    ).order_by(
        func.date(models.Task.updated_at)
    ).all()

    result_map = {c.contribution_date: c.task_count for c in contributions}

    # Fill in dates with 0 contributions
    all_dates = [start_date + timedelta(days=i) for i in range(days_ago)]

    formatted_results = [
        schemas.ContributionData(date=d, count=result_map.get(d, 0))
        for d in all_dates
    ]
    return formatted_results

